R["py-checkpoint-problem-solving"] = "sales = [(\"mon\", \"pen\", 4), (\"mon\", \"book\", 2), (\"tue\", \"pen\", 3), (\"wed\", \"bag\", 5), (\"wed\", \"book\", 7)]\n\n\ndef report(sales):\n    per_item = {}\n    item_last = {}\n    per_day = {}\n    total = 0\n    for idx, (day, item, qty) in enumerate(sales):\n        per_item[item] = per_item.get(item, 0) + qty\n        item_last[item] = idx\n        per_day[day] = per_day.get(day, 0) + qty\n        total += qty\n    best_item = min(per_item, key=lambda it: (-per_item[it], item_last[it]))\n    best_day = sorted(per_day, key=lambda d: (-per_day[d], d))[0]\n    return {\"total\": total, \"best_item\": best_item, \"busiest_day\": best_day}\n\n\nprint(report(sales))";
W["py-checkpoint-problem-solving"] = "sales = [(\"mon\", \"pen\", 4), (\"mon\", \"book\", 2), (\"tue\", \"pen\", 3), (\"wed\", \"bag\", 5), (\"wed\", \"book\", 7)]\n\n\ndef report(sales):\n    per_item = {}\n    per_day = {}\n    total = 0\n    for day, item, qty in sales:\n        per_item[item] = per_item.get(item, 0) + qty\n        per_day[day] = per_day.get(day, 0) + qty\n        total += qty\n    best_item = max(per_item, key=per_item.get)\n    best_day = max(per_day, key=per_day.get)\n    return {\"total\": total, \"best_item\": best_item, \"busiest_day\": best_day}\n\n\nprint(report(sales))";
