W["py-cap-summary"] = "def finance_summary(expenses, budget):\n    if not expenses:\n        return {\"total\": 0.0, \"count\": 0, \"top\": None,\n                \"remaining\": round(budget, 2), \"warning\": False}\n    totals = {}\n    for e in expenses:\n        totals[e[\"category\"]] = totals.get(e[\"category\"], 0) + e[\"amount\"]\n    total = round(sum(e[\"amount\"] for e in expenses), 2)\n    top = max(totals, key=totals.get)\n    return {\n        \"total\": total,\n        \"count\": len(expenses),\n        \"top\": top,\n        \"remaining\": round(budget - total, 2),\n        \"warning\": total > 0.9 * budget,\n    }";
