R["pa-checkpoint-datamodel"] = "class Node:\n    __slots__ = ('value', 'next')\n\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\nclass LinkedList:\n    __slots__ = ('_head',)\n\n    def __init__(self, items=()):\n        self._head = None\n        for x in reversed(list(items)):\n            self._head = Node(x, self._head)\n\n    def __len__(self):\n        n = 0\n        cur = self._head\n        while cur is not None:\n            n += 1\n            cur = cur.next\n        return n\n\n    def __iter__(self):\n        cur = self._head\n        while cur is not None:\n            yield cur.value\n            cur = cur.next\n\n    def __getitem__(self, index):\n        if isinstance(index, slice):\n            start, stop, step = index.indices(len(self))\n            out = LinkedList()\n            for i, v in enumerate(self):\n                if start <= i < stop and (i - start) % step == 0:\n                    out._append(v)\n            return out\n        if index < 0:\n            index += len(self)\n        for i, v in enumerate(self):\n            if i == index:\n                return v\n        raise IndexError('index out of range')\n\n    def __contains__(self, x):\n        return any(v == x for v in self)\n\n    def __repr__(self):\n        return 'LinkedList(' + ' -> '.join(repr(v) for v in self) + ')'\n\n    def _append(self, x):\n        node = Node(x)\n        if self._head is None:\n            self._head = node\n            return\n        cur = self._head\n        while cur.next is not None:\n            cur = cur.next\n        cur.next = node\n\n    def prepend(self, x):\n        self._head = Node(x, self._head)\n\n    def reverse(self):\n        out = LinkedList()\n        for v in self:\n            out.prepend(v)\n        return out";
