R["pa-mt-class-decorator"] = "def dataclassish(cls):\n    fields = list(cls.__annotations__)\n\n    if '__init__' not in vars(cls):\n        def __init__(self, *args, __fields=tuple(fields), **kwargs):\n            if len(args) > len(__fields):\n                raise TypeError('too many arguments')\n            for name, value in zip(__fields, args):\n                setattr(self, name, value)\n            for name in __fields[len(args):]:\n                if name not in kwargs:\n                    raise TypeError(f'missing field: {name}')\n                setattr(self, name, kwargs.pop(name))\n            if kwargs:\n                raise TypeError(f'unexpected fields: {sorted(kwargs)}')\n        cls.__init__ = __init__\n\n    def __repr__(self):\n        inner = ', '.join(f'{f}={getattr(self, f)!r}' for f in fields)\n        return f'{type(self).__name__}({inner})'\n\n    def __eq__(self, other):\n        if not isinstance(other, type(self)) or not isinstance(self, type(other)):\n            return NotImplemented\n        return all(getattr(self, f) == getattr(other, f) for f in fields)\n\n    if '__repr__' not in vars(cls):\n        cls.__repr__ = __repr__\n    if '__eq__' not in vars(cls):\n        cls.__eq__ = __eq__\n    return cls\n\n\n@dataclassish\nclass Point:\n    x: int\n    y: int\n\n\n@dataclassish\nclass Named:\n    name: str\n\n    def __init__(self, name):\n        self.name = 'Dr ' + name";
