R["pa-checkpoint-metaprogramming"] = "def timed(cls):\n    import functools, time\n    for name, fn in list(vars(cls).items()):\n        if callable(fn) and not name.startswith('_'):\n            def make(f, fname):\n                @functools.wraps(f)\n                def wrapper(self, *a, **kw):\n                    start = time.perf_counter()\n                    try:\n                        return f(self, *a, **kw)\n                    finally:\n                        type(self).__timings__.setdefault(fname, []).append(time.perf_counter() - start)\n                return wrapper\n            setattr(cls, name, make(fn, name))\n    if not hasattr(cls, '__timings__'):\n        cls.__timings__ = {}\n    return cls\n\n\n@timed\nclass Service:\n    def work(self, n):\n        total = 0\n        for i in range(n):\n            total += i\n        return total\n\n    def _private(self):\n        return 'hidden'";
