W["pa-checkpoint-concurrency"] = "from concurrent.futures import ThreadPoolExecutor, as_completed\nimport threading\n\n\ndef run_jobs(jobs, workers=3, retries=2):\n    attempts = {}\n    attempts_lock = threading.Lock()\n\n    def attempt_once(idx):\n        with attempts_lock:\n            n = attempts.get(idx, 0)\n            attempts[idx] = n + 1\n        return jobs[idx]()\n\n    succeeded = {}\n    failed = []\n    with ThreadPoolExecutor(max_workers=workers) as pool:\n        futures = {pool.submit(attempt_once, i): i for i in range(len(jobs))}\n        for fut in as_completed(futures):\n            idx = futures[fut]\n            try:\n                succeeded[idx] = fut.result()\n            except Exception:\n                n = attempts[idx]\n                if n <= retries:\n                    # WRONG: resubmits but discards the future \u2014 never awaited,\n                    # so the retried job's outcome is lost\n                    pool.submit(attempt_once, idx)\n                else:\n                    failed.append(idx)\n    return {'succeeded': succeeded, 'failed': sorted(failed)}";
