R["pa-async-bounded-pipeline"] = "import asyncio\n\n\nasync def pipeline(items, transform, workers=2, maxsize=3):\n    q = asyncio.Queue(maxsize=maxsize)\n    out = []\n\n    async def worker():\n        while True:\n            item = await q.get()\n            try:\n                out.append(await transform(item))\n            finally:\n                q.task_done()\n\n    tasks = []\n    for _ in range(workers):\n        tasks.append(asyncio.create_task(worker()))\n    for it in items:\n        await q.put(it)\n    await q.join()\n    for t in tasks:\n        t.cancel()\n    return sorted(out)";
W["pa-async-bounded-pipeline"] = "import asyncio\n\n\nasync def pipeline(items, transform, workers=2, maxsize=3):\n    q = asyncio.Queue(maxsize=maxsize)\n    out = []\n\n    async def worker():\n        while True:\n            item = await q.get()\n            try:\n                out.append(await transform(item))\n            finally:\n                pass  # WRONG: task_done() never called \u2014 q.join() waits forever\n\n    tasks = []\n    for _ in range(workers):\n        tasks.append(asyncio.create_task(worker()))\n    for it in items:\n        await q.put(it)\n    await q.join()\n    for t in tasks:\n        t.cancel()\n    return sorted(out)";
R["pa-async-rate-limited-service"] = "import asyncio\n\n\nclass RateLimitedClient:\n    def __init__(self, max_concurrent=2):\n        self._sem = asyncio.Semaphore(max_concurrent)\n        self.in_flight = 0\n\n    async def request(self, name, delay, fail=False):\n        async with self._sem:\n            self.in_flight += 1\n            try:\n                await asyncio.sleep(delay)\n                if fail:\n                    raise RuntimeError(f'{name} failed')\n                return f'{name}:ok'\n            finally:\n                self.in_flight -= 1\n\n    async def run_all(self, specs, per_request_timeout=None):\n        results = [None] * len(specs)\n        async with asyncio.TaskGroup() as tg:\n            tasks = []\n            for i, (name, delay, fail) in enumerate(specs):\n                coro = self.request(name, delay, fail)\n                if per_request_timeout is not None:\n                    coro = self._guarded(coro, per_request_timeout, i, results)\n                else:\n                    coro = self._guarded(coro, None, i, results)\n                tasks.append(tg.create_task(coro))\n        return results\n\n    async def _guarded(self, coro, seconds, i, results):\n        if seconds is None:\n            results[i] = await coro\n            return\n        try:\n            async with asyncio.timeout(seconds):\n                results[i] = await coro\n        except TimeoutError:\n            results[i] = f'timeout:{seconds}'";
W["pa-async-rate-limited-service"] = "import asyncio\n\n\nclass RateLimitedClient:\n    def __init__(self, max_concurrent=2):\n        self._sem = asyncio.Semaphore(max_concurrent)\n        self.in_flight = 0\n\n    async def request(self, name, delay, fail=False):\n        # WRONG: no semaphore around the work \u2014 concurrency unbounded,\n        # and in_flight tracking happens outside any critical section\n        self.in_flight += 1\n        await asyncio.sleep(delay)\n        self.in_flight -= 1\n        if fail:\n            raise RuntimeError(f'{name} failed')\n        return f'{name}:ok'\n\n    async def run_all(self, specs, per_request_timeout=None):\n        results = [None] * len(specs)\n        async with asyncio.TaskGroup() as tg:\n            for i, (name, delay, fail) in enumerate(specs):\n                tg.create_task(self.request(name, delay, fail))\n        return results";
R["pa-checkpoint-async"] = "import asyncio\n\n\nasync def fetch_all(jobs):\n    '''Run zero-arg async jobs with per-job timeout. Returns\n    [(index, value_or_'timeout:<seconds>')]; a REAL job error still raises.'''\n    results = [None] * len(jobs)\n    async with asyncio.TaskGroup() as tg:\n        for i, job in enumerate(jobs):\n            async def one(j=job, i=i):\n                try:\n                    async with asyncio.timeout(0.05):\n                        results[i] = (i, await j())\n                except TimeoutError:\n                    results[i] = (i, 'timeout:0.05')\n            tg.create_task(one())\n    return results";
W["pa-checkpoint-async"] = "import asyncio\n\n\nasync def fetch_all(jobs):\n    '''WRONG: catches EVERYTHING including CancelledError raised by the\n    TaskGroup on sibling failure \u2014 breaking structured concurrency and\n    also masking timeouts with a blanket except.'''\n    results = [None] * len(jobs)\n    async with asyncio.TaskGroup() as tg:\n        for i, job in enumerate(jobs):\n            async def one(j=job, i=i):\n                try:\n                    async with asyncio.timeout(0.05):\n                        results[i] = (i, await j())\n                except BaseException:\n                    results[i] = (i, 'timeout:0.05')\n            tg.create_task(one())\n    return results";
R["pa-perf-memo-fib"] = "def fib(n, memo, stats):\n    stats['calls'] += 1\n    if n <= 1:\n        return n\n    if n in memo:\n        return memo[n]\n    result = fib(n - 1, memo, stats) + fib(n - 2, memo, stats)\n    memo[n] = result\n    return result";
W["pa-perf-memo-fib"] = "def fib(n, memo, stats):\n    stats['calls'] += 1\n    if n <= 1:\n        return n\n    # WRONG: writes the memo but never reads it \u2014 exponential calls remain\n    result = fib(n - 1, memo, stats) + fib(n - 2, memo, stats)\n    memo[n] = result\n    return result";
R["pa-perf-hotspot"] = "import cProfile\nimport pstats\n\n\ndef hotspot_name(workload):\n    '''Run workload() under cProfile; return the funcname with the highest\n    tottime (self time), excluding the workload function itself.'''\n    pr = cProfile.Profile()\n    pr.enable()\n    workload()\n    pr.disable()\n    st = pstats.Stats(pr)\n    best, best_tt = None, -1.0\n    for (fn, lineno, name), (cc, nc, tt, ct, callers) in st.stats.items():\n        if name == 'workload':\n            continue\n        if tt > best_tt:\n            best, best_tt = name, tt\n    return best";
W["pa-perf-hotspot"] = "import cProfile\nimport pstats\n\n\ndef hotspot_name(workload):\n    '''WRONG: sorts by cumtime instead of tottime \u2014 always names an outer\n    wrapper (or the workload itself), never the real hotspot.'''\n    pr = cProfile.Profile()\n    pr.enable()\n    workload()\n    pr.disable()\n    st = pstats.Stats(pr)\n    best, best_ct = None, -1.0\n    for (fn, lineno, name), (cc, nc, tt, ct, callers) in st.stats.items():\n        if ct > best_ct:\n            best, best_ct = name, ct\n    return best";
