R["pa-checkpoint-performance"] = "def fetch_user_orders(user_ids, db):\n    '''db.query(sql_template, ids) counts queries; fetch ALL users' orders\n    in AT MOST 2 queries and return {user_id: [order, ...]}.'''\n    if not user_ids:\n        return {}\n    rows = db.query('SELECT user_id, id, total FROM orders WHERE user_id IN ?', [user_ids])\n    out = {uid: [] for uid in user_ids}\n    for user_id, oid, total in rows:\n        out[user_id].append({'id': oid, 'total': total})\n    return out";
W["pa-checkpoint-performance"] = "def fetch_user_orders(user_ids, db):\n    '''WRONG: the classic N+1 \u2014 one query per user.'''\n    out = {}\n    for uid in user_ids:\n        rows = db.query('SELECT id, total FROM orders WHERE user_id = ?', [uid])\n        out[uid] = [{'id': oid, 'total': t} for (oid, t) in rows]\n    return out";
R["pa-int-dis-opnames"] = "import dis\n\n\ndef instruction_names(func):\n    '''Return the list of instruction opnames for func, in order.'''\n    return [ins.opname for ins in dis.get_instructions(func)]\n\n\ndef loop_loads_global(func, name):\n    hits = 0\n    for ins in dis.get_instructions(func):\n        if ins.opname == 'LOAD_GLOBAL' and ins.argrepr == name:\n            hits += 1\n    return hits >= 2";
