R["pa-int-weak-cache"] = "import weakref\n\n\nclass WeakCache:\n    '''Caches objects by key WITHOUT keeping them alive; missing or\n    collected entries return None (via default_factory when given).'''\n    def __init__(self, default_factory=None):\n        self._refs = {}\n        self._factory = default_factory\n\n    def get(self, key):\n        ref = self._refs.get(key)\n        obj = ref() if ref is not None else None\n        if obj is None:\n            if self._factory is not None:\n                obj = self._factory(key)\n                self._refs[key] = weakref.ref(obj)\n            return obj\n        return obj\n\n    def put(self, key, obj):\n        self._refs[key] = weakref.ref(obj)";
W["pa-int-weak-cache"] = "import weakref\n\n\nclass WeakCache:\n    def __init__(self, default_factory=None):\n        # WRONG: stores STRONG references \u2014 objects never become collectable\n        self._refs = {}\n        self._factory = default_factory\n\n    def get(self, key):\n        obj = self._refs.get(key)\n        if obj is None and self._factory is not None:\n            obj = self._factory(key)\n            self._refs[key] = obj\n        return obj\n\n    def put(self, key, obj):\n        self._refs[key] = obj";
R["pa-int-import-cache"] = "import sys\nimport types\n\n\nclass ReloadableModule:\n    def __init__(self):\n        self.modules = {}\n\n    def install(self, name):\n        mod = types.ModuleType(name)\n        mod.exec_count = 0\n        sys.modules[name] = mod\n        self.modules[name] = mod\n        return mod\n\n    def import_again(self, name):\n        return sys.modules[name]\n\n    def simulate_body_execution(self, name):\n        sys.modules[name].exec_count += 1\n\n    def identity_stable(self, name):\n        target = sys.modules[name]\n        return all(self.import_again(name) is target for _ in range(3))";
W["pa-int-import-cache"] = "import sys\nimport types\n\n\nclass ReloadableModule:\n    def __init__(self):\n        self.modules = {}\n\n    def install(self, name):\n        mod = types.ModuleType(name)\n        mod.exec_count = 0\n        sys.modules[name] = mod\n        self.modules[name] = mod\n        return mod\n\n    def import_again(self, name):\n        # WRONG: creates a fresh module object each call \u2014 breaks identity\n        mod = types.ModuleType(name)\n        mod.exec_count = 0\n        sys.modules[name] = mod\n        return mod\n\n    def simulate_body_execution(self, name):\n        sys.modules[name].exec_count += 1\n\n    def identity_stable(self, name):\n        target = sys.modules[name]\n        return all(self.import_again(name) is target for _ in range(3))";
