R["pa-arch-refactor-pipeline"] = "def process_orders(orders, notifier, audit):\n    '''Refactored contract (behavior preserved):\n    - orders with total <= 0 are SKIPPED (still logged to audit as 'skipped')\n    - valid orders are notified then audited as 'sent'\n    - notification failure aborts the batch: audit gets 'failed', and the\n      exception PROPAGATES after logging\n    Returns the audit list.'''\n    for order in orders:\n        if order['total'] <= 0:\n            audit.append({'id': order['id'], 'status': 'skipped'})\n            continue\n        try:\n            notifier.send(order['email'], f\"order {order['id']} confirmed\")\n        except Exception:\n            audit.append({'id': order['id'], 'status': 'failed'})\n            raise\n        audit.append({'id': order['id'], 'status': 'sent'})\n    return audit";
W["pa-arch-refactor-pipeline"] = "def process_orders(orders, notifier, audit):\n    '''WRONG: swallows the notification failure \u2014 the batch continues and\n    no exception propagates, breaking the documented behavior.'''\n    for order in orders:\n        if order['total'] <= 0:\n            audit.append({'id': order['id'], 'status': 'skipped'})\n            continue\n        try:\n            notifier.send(order['email'], f\"order {order['id']} confirmed\")\n        except Exception:\n            audit.append({'id': order['id'], 'status': 'failed'})\n            continue\n        audit.append({'id': order['id'], 'status': 'sent'})\n    return audit";
