R["pa-api-error-envelope"] = "TITLES = {\n    400: 'bad_request',\n    404: 'not_found',\n    409: 'conflict',\n    422: 'validation_failed',\n    429: 'rate_limited',\n    500: 'internal_error',\n}\n\n\ndef error_envelope(status, detail=None, field=None):\n    envelope = {\n        'error': {\n            'status': status,\n            'title': TITLES[status],\n        }\n    }\n    if field is not None:\n        envelope['error']['field'] = field\n    if status >= 500:\n        envelope['error']['detail'] = 'an unexpected error occurred'\n    elif detail is not None:\n        envelope['error']['detail'] = detail\n    return envelope\n";
