R["pa-api-router"] = "class RouterError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n\n\nclass Router:\n    def __init__(self):\n        self._routes = {}\n\n    def add(self, method, path, handler):\n        parts = tuple(path.strip('/').split('/'))\n        self._routes[(method, parts)] = handler\n\n    @staticmethod\n    def _match(pattern, actual):\n        if len(pattern) != len(actual):\n            return None\n        params = {}\n        for p, a in zip(pattern, actual):\n            if p.startswith('{') and p.endswith('}'):\n                params[p[1:-1]] = a\n            elif p != a:\n                return None\n        return params\n\n    def dispatch(self, method, path):\n        actual = tuple(path.strip('/').split('/'))\n        handler = self._routes.get((method, actual))\n        if handler is not None:\n            return handler({})\n        for (m, pattern), handler in self._routes.items():\n            params = self._match(pattern, actual)\n            if params is not None:\n                if m == method:\n                    return handler(params)\n                raise RouterError(405, 'method not allowed')\n        raise RouterError(404, 'not found')\n";
