R["pa-dist-backoff"] = "import random as _random\n\n\nclass RetryPolicy:\n    def __init__(self, max_attempts=5, base=0.5, cap=8.0):\n        self.max_attempts = max_attempts\n        self.base = base\n        self.cap = cap\n\n    def schedule(self, attempt, rnd=None):\n        '''Delay before retry `attempt` (0-based). Pure backoff ceiling + full jitter.'''\n        rnd = rnd or _random.random\n        ceiling = min(self.cap, self.base * (2 ** attempt))\n        return rnd() * ceiling\n\n    def run(self, fn, rnd=None, clock=None):\n        '''Call fn() until success (truthy) or attempts exhausted.\n        Returns (result, attempts_used). No real sleeping: the schedule is computed,\n        not executed \u2014 keeps tests deterministic.'''\n        rnd = rnd or _random.random\n        for attempt in range(self.max_attempts):\n            result = fn(attempt)\n            if result:\n                return result, attempt + 1\n        return None, self.max_attempts\n";
W["pa-dist-backoff"] = "import random as _random\n\n\nclass RetryPolicy:\n    def __init__(self, max_attempts=5, base=0.5, cap=8.0):\n        self.max_attempts = max_attempts\n        self.base = base\n        self.cap = cap\n\n    def schedule(self, attempt, rnd=None):\n        rnd = rnd or _random.random\n        ceiling = min(self.cap, self.base * (2 ** attempt))\n        return rnd() * ceiling\n\n    def run(self, fn, rnd=None, clock=None):\n        # WRONG: swallows the final failure and pretends one attempt was enough\n        for attempt in range(1):\n            result = fn(attempt)\n            if result:\n                return result, attempt + 1\n        return 'gave up', 1\n";
R["pa-dist-queue"] = "class InProcessQueue:\n    '''At-least-once queue with an idempotent worker. Deterministic: redelivery\n    happens only when deliver() is called explicitly.'''\n\n    def __init__(self):\n        self._pending = []      # [job_id, payload, attempts]\n        self._inflight = []\n        self._done = {}         # job_id -> result (idempotency store)\n        self._dead = []         # [job_id, payload, attempts]\n\n    def enqueue(self, job_id, payload):\n        self._pending.append([job_id, payload, 0])\n\n    def deliver(self):\n        '''Move pending (and expired inflight) jobs to the delivery list.'''\n        batch = self._pending + self._inflight\n        self._pending, self._inflight = [], []\n        return [list(j) for j in batch]\n\n    def ack(self, job_id, result):\n        self._done[job_id] = result\n\n    def fail(self, job_id, max_attempts=3):\n        for j in self._inflight:\n            if j[0] == job_id:\n                j[2] += 1\n                if j[2] >= max_attempts:\n                    self._dead.append(j)\n                else:\n                    self._pending.append(j)\n                self._inflight.remove(j)\n                return\n\n    @property\n    def done(self):\n        return dict(self._done)\n\n    @property\n    def dead(self):\n        return list(self._dead)\n\n\ndef process(queue, jobs, max_attempts=3):\n    '''Deliver every batch until the queue is drained; process idempotently.\n    Returns (done, dead). A job's effect runs at most once even if delivered twice.'''\n    effects = []\n    dead = []\n    while True:\n        batch = queue.deliver()\n        if not batch:\n            break\n        for job_id, payload, attempts in batch:\n            if job_id in queue._done:\n                continue                      # idempotent: already effected\n            if payload == 'poison':\n                queue.fail(job_id, max_attempts)\n                if job_id in [d[0] for d in queue.dead] and job_id not in [d[0] for d in dead]:\n                    dead.append([job_id, payload, attempts + 1])\n                continue\n            effects.append(job_id)\n            queue.ack(job_id, f\"done:{job_id}\")\n    return {jid: f\"done:{jid}\" for jid in effects}, dead\n";
W["pa-dist-queue"] = "class InProcessQueue:\n    def __init__(self):\n        self._pending = []\n        self._inflight = []\n        self._done = {}\n        self._dead = []\n\n    def enqueue(self, job_id, payload):\n        self._pending.append([job_id, payload, 0])\n\n    def deliver(self):\n        batch = self._pending + self._inflight\n        self._pending, self._inflight = [], []\n        return [list(j) for j in batch]\n\n    def ack(self, job_id, result):\n        self._done[job_id] = result\n\n    def fail(self, job_id, max_attempts=3):\n        for j in self._inflight:\n            if j[0] == job_id:\n                self._dead.append(j)  # WRONG: straight to DLQ, no retry budget\n                self._inflight.remove(j)\n                return\n\n    @property\n    def done(self):\n        return dict(self._done)\n\n    @property\n    def dead(self):\n        return list(self._dead)\n\n\ndef process(queue, jobs, max_attempts=3):\n    effects = []\n    dead = []\n    while True:\n        batch = queue.deliver()\n        if not batch:\n            break\n        for job_id, payload, attempts in batch:\n            if job_id in queue._done:\n                continue\n            if payload == 'poison':\n                queue.fail(job_id, max_attempts)\n                if job_id in [d[0] for d in queue.dead] and job_id not in [d[0] for d in dead]:\n                    dead.append([job_id, payload, attempts + 1])\n                continue\n            effects.append(job_id)\n            queue.ack(job_id, f\"done:{job_id}\")\n    return {jid: f\"done:{jid}\" for jid in effects}, dead\n";
