R["pa-dist-queue"] = "class InProcessQueue:\n    '''At-least-once queue. deliver() hands out every pending job and keeps them\n    in-flight; delivered-but-un-acked jobs are re-delivered on the NEXT deliver()\n    (the lease-expiry redelivery).'''\n\n    def __init__(self):\n        self._pending = []      # [job_id, payload, attempts]\n        self._inflight = []\n        self._done = {}         # job_id -> result (idempotency store)\n        self._dead = []\n\n    def enqueue(self, job_id, payload):\n        self._pending.append([job_id, payload, 0])\n\n    def deliver(self):\n        batch = self._pending\n        self._pending = []\n        redelivered = self._inflight\n        self._inflight = [list(j) for j in batch]\n        self._inflight += [list(j) for j in redelivered]\n        return [list(j) for j in batch + redelivered]\n\n    def ack(self, job_id, result):\n        self._done[job_id] = result\n        self._inflight = [j for j in self._inflight if j[0] != job_id]\n\n    def fail(self, job_id, max_attempts=3):\n        for j in self._inflight:\n            if j[0] == job_id:\n                j[2] += 1\n                self._inflight.remove(j)\n                if j[2] >= max_attempts:\n                    self._dead.append(j)\n                else:\n                    self._pending.append(j)\n                return\n\n    @property\n    def done(self):\n        return dict(self._done)\n\n    @property\n    def dead(self):\n        return list(self._dead)\n\n\ndef process(queue, jobs, max_attempts=3):\n    '''Deliver every batch until the queue stays empty. Idempotent: jobs already\n    in done are skipped; poison exhausts its retry budget into the DLQ.\n    Returns the queue's full (done, dead) state.'''\n    while True:\n        batch = queue.deliver()\n        if not batch:\n            break\n        for job_id, payload, attempts in batch:\n            if job_id in queue._done:\n                queue.ack(job_id, queue._done[job_id])  # idempotent re-ack of the redelivery\n                continue\n            if any(d[0] == job_id for d in queue._dead):\n                continue\n            if payload == 'poison':\n                queue.fail(job_id, max_attempts)\n                continue\n            queue.ack(job_id, f\"done:{job_id}\")\n    return queue.done, queue.dead\n";
