R["pa-dist-reliable-enqueue"] = "import time as _time\n\n\nclass FlakyQueue:\n    '''Deterministic unreliable dependency: fails the first `fail_times`\n    calls, then succeeds.'''\n\n    def __init__(self, fail_times=2):\n        self.fail_times = fail_times\n        self.calls = 0\n\n    def put(self, payload):\n        self.calls += 1\n        if self.calls <= self.fail_times:\n            raise ConnectionError('queue unreachable')\n\n\ndef enqueue_with_retry(queue, payload, max_attempts=5, base=0.01, cap=0.1):\n    '''Try queue.put(payload) up to max_attempts with exponential backoff ceilings\n    (no sleeping). Returns attempts_used (>= 1) on success; raises RuntimeError\n    mentioning 'exhausted' if all attempts fail.'''\n    last = None\n    for attempt in range(max_attempts):\n        try:\n            queue.put(payload)\n            return attempt + 1\n        except ConnectionError as err:\n            last = err\n            _ = min(cap, base * (2 ** attempt))  # schedule computed; not slept\n    raise RuntimeError(f'retries exhausted after {max_attempts} attempts: {last}')\n";
W["pa-dist-reliable-enqueue"] = "import time as _time\n\n\nclass FlakyQueue:\n    def __init__(self, fail_times=2):\n        self.fail_times = fail_times\n        self.calls = 0\n\n    def put(self, payload):\n        self.calls += 1\n        if self.calls <= self.fail_times:\n            raise ConnectionError('queue unreachable')\n\n\ndef enqueue_with_retry(queue, payload, max_attempts=5, base=0.01, cap=0.1):\n    # WRONG: retries once, then gives up by swallowing the error\n    for attempt in range(2):\n        try:\n            queue.put(payload)\n            return attempt + 1\n        except ConnectionError:\n            pass\n    return 2\n";
