R["pa-db-decompose"] = "def decompose(rows):\n    '''rows: list of dicts with keys customer_id, customer_name, order_id, total.\n    Returns (customers, orders): customers = {customer_id: customer_name},\n    orders = [{'order_id': ..., 'customer_id': ..., 'total': ...}] in first-seen\n    order of their order_id. Redundant customer names must agree; conflicting\n    duplicates raise ValueError('conflicting customer name').'''\n    customers = {}\n    orders = []\n    seen = set()\n    for row in rows:\n        cid = row['customer_id']\n        name = row['customer_name']\n        if cid in customers and customers[cid] != name:\n            raise ValueError('conflicting customer name')\n        customers[cid] = name\n        if row['order_id'] not in seen:\n            seen.add(row['order_id'])\n            orders.append({\n                'order_id': row['order_id'],\n                'customer_id': cid,\n                'total': row['total'],\n            })\n    return customers, orders\n";
