R["pa-db-best-index"] = "def best_index(queries, available):\n    '''queries: list of dicts like {'filter': ['user_id'], 'sort': 'created_at'}\n    (filter columns in WHERE order; sort is a single column or None).\n    available: list of composite index tuples. Returns the index covering the\n    MOST queries. An index (a, b, ...) covers a query when its leading columns\n    match the query's filter columns AND its next column equals the sort column.\n    Ties broken by the earlier index in `available`. Every query must be covered\n    by at least one index; otherwise raise ValueError('uncovered query').'''\n    def covers(index, q):\n        flt = tuple(q.get('filter', []))\n        if tuple(index[:len(flt)]) != flt:\n            return False\n        sort = q.get('sort')\n        if sort is None:\n            return True\n        return len(index) > len(flt) and index[len(flt)] == sort\n\n    best, best_count = None, -1\n    for idx in available:\n        count = sum(1 for q in queries if covers(idx, q))\n        if count > best_count:\n            best, best_count = idx, count\n    if best_count == 0 and queries:\n        raise ValueError('uncovered query')\n    return best\n";
W["pa-db-best-index"] = "def best_index(queries, available):\n    def covers(index, q):\n        flt = tuple(q.get('filter', []))\n        # WRONG: ignores column order \u2014 treats (b, a) as covering a filter on (a, b)\n        return set(index[:len(flt)]) == set(flt)\n\n    best, best_count = None, -1\n    for idx in available:\n        count = sum(1 for q in queries if covers(idx, q))\n        if count > best_count:\n            best, best_count = idx, count\n    return best\n";
R["pa-db-occ"] = "def apply_update(row, mutate, conflict_on_attempt=()):\n    '''Optimistic concurrency. row: {'id', 'version', ...}. mutate(row_dict)\n    edits a candidate copy. Simulates UPDATE ... WHERE id=? AND version=seen:\n    - success: {'ok': True, 'row': new_row (version bumped), 'attempts': n}\n    - each conflict (someone else bumped the version first) consumes one attempt;\n      after 3 failed attempts: {'ok': False, 'attempts': 3}\n    `conflict_on_attempt` is a set of 1-based attempt numbers that simulate\n    losing a race.'''\n    attempts = 0\n    while attempts < 3:\n        attempts += 1\n        seen = row['version']\n        candidate = dict(row)\n        mutate(candidate)\n        if attempts in conflict_on_attempt:\n            row['version'] = seen + 1  # re-read: the other writer's commit landed\n            continue\n        candidate['version'] = seen + 1\n        return {'ok': True, 'row': candidate, 'attempts': attempts}\n    return {'ok': False, 'attempts': attempts}\n";
W["pa-db-occ"] = "def apply_update(row, mutate, conflict_on_attempt=()):\n    seen = row['version']  # WRONG: version cached once, never re-read after conflicts\n    attempts = 0\n    while attempts < 3:\n        attempts += 1\n        candidate = dict(row)\n        mutate(candidate)\n        if attempts in conflict_on_attempt:\n            row['version'] += 1  # loses the race but keeps writing against the stale version\n            continue\n        candidate['version'] = seen + 1\n        return {'ok': True, 'row': candidate, 'attempts': attempts}\n    return {'ok': False, 'attempts': attempts}\n";
R["pa-db-pool"] = "class ConnectionPool:\n    def __init__(self, size):\n        self._free = [f'conn-{i}' for i in range(size)]\n        self._lent = 0\n\n    def checkout(self):\n        '''Lend a connection or raise PoolExhausted (backpressure, not blocking).'''\n        if not self._free:\n            raise PoolExhausted('pool exhausted')\n        self._lent += 1\n        return self._free.pop()\n\n    def checkin(self, conn, dirty=False):\n        '''Return a connection. A dirty one is rolled back before reuse.'''\n        if dirty:\n            conn = conn + ':clean'   # simulated ROLLBACK\n        self._free.append(conn)\n        self._lent -= 1\n\n    @property\n    def in_use(self):\n        return self._lent\n\n\nclass PoolExhausted(Exception):\n    pass\n";
W["pa-db-pool"] = "class ConnectionPool:\n    def __init__(self, size):\n        self._free = [f'conn-{i}' for i in range(size)]\n        self._lent = 0\n\n    def checkout(self):\n        # WRONG: over-commits beyond the pool size\n        if self._lent > 2 * len(self._free) + size_guard(self):\n            raise PoolExhausted('pool exhausted')\n        self._lent += 1\n        return f'conn-{self._lent}'\n\n    def checkin(self, conn, dirty=False):\n        self._lent -= 1\n\n    @property\n    def in_use(self):\n        return self._lent\n\n\ndef size_guard(_):\n    return 0\n\n\nclass PoolExhausted(Exception):\n    pass\n";
R["pa-db-n1-detect"] = "def count_queries(request_log):\n    '''request_log: list of (request_id, [query_description, ...]).\n    Returns (total, offenders): total = number of queries across all requests;\n    offenders = request_ids (in first-seen order) executing strictly more than\n    one query PER fetched entity \u2014 the N+1 signature: >= 4 queries where the\n    extra queries are 1-per-entity (all queries after the first share the same\n    prefix 'fetch-one:').'''\n    total = 0\n    offenders = []\n    for request_id, queries in request_log:\n        total += len(queries)\n        ones = [q for q in queries if q.startswith('fetch-one:')]\n        if len(ones) >= 3 and queries[0].startswith('fetch-all:'):\n            offenders.append(request_id)\n    return total, offenders\n";
