R["pa-db-repository"] = "class OrderNotFound(Exception):\n    pass\n\n\nclass OrderRepository:\n    '''Domain-shaped repository over an in-memory table (list of row dicts).'''\n\n    def __init__(self, rows=None):\n        self._rows = list(rows or [])\n\n    def get(self, order_id):\n        for row in self._rows:\n            if row['id'] == order_id:\n                return dict(row)\n        raise OrderNotFound(f'order {order_id} not found')\n\n    def add(self, order_id, total, customer_id):\n        if any(r['id'] == order_id for r in self._rows):\n            raise ValueError('duplicate order id')\n        self._rows.append({'id': order_id, 'total': total, 'customer_id': customer_id})\n\n    def for_customer(self, customer_id):\n        return [dict(r) for r in self._rows if r['customer_id'] == customer_id]\n";
