R["pa-db-inventory-checkout"] = "def checkout(rows, requests):\n    state = {r['sku']: dict(r) for r in rows}\n    applied, out = [], []\n    for sku, conflicts in requests:\n        attempts = 0\n        done = False\n        while attempts < 3 and not done:\n            attempts += 1\n            row = dict(state[sku])\n            if attempts in conflicts:\n                row['version'] += 1\n                state[sku] = row\n                continue\n            if row['stock'] <= 0:\n                out.append(sku)\n                done = True\n                continue\n            row['stock'] -= 1\n            row['version'] = row['version'] + 1\n            state[sku] = row\n            applied.append(sku)\n            done = True\n        if not done and sku not in out:\n            out.append(sku)\n    return {'rows': list(state.values()), 'applied': applied, 'out_of_stock': out}\n";
