R["pa-sec-parameterize"] = "import re as _re\n\n\nclass UnsafeQuery(Exception):\n    pass\n\n\ndef build_query(template, params):\n    '''Simulate parameterization. The template may contain ? placeholders; params\n    are values. Values NEVER change the statement, so any quote in a value is\n    stored literally. Raises UnsafeQuery on placeholder count mismatch.'''\n    count = template.count('?')\n    if count != len(params):\n        raise UnsafeQuery('placeholder count mismatch')\n    parts = template.split('?')\n    rendered = parts[0]\n    for i, value in enumerate(params):\n        rendered += repr(value) + parts[i + 1]\n    return rendered, 'parameterized'\n\n\ndef vulnerable_query(template, values):\n    '''The WRONG world: values are formatted straight into the SQL string.\n    Detects classic payloads and raises UnsafeQuery (i.e., flags that this\n    build path is unsafe for them).'''\n    rendered = template.format(*values)\n    lowered = rendered.lower()\n    if \"drop table\" in lowered or \"or 1=1\" in lowered or \";\" in lowered:\n        raise UnsafeQuery('injection detected in string-built query')\n    return rendered\n";
W["pa-sec-parameterize"] = "import re as _re\n\n\nclass UnsafeQuery(Exception):\n    pass\n\n\ndef build_query(template, params):\n    '''Simulate parameterization. The template may contain ? placeholders; params\n    are values. Values NEVER change the statement, so any quote in a value is\n    stored literally. Raises UnsafeQuery on placeholder count mismatch.'''\n    count = template.count('?')\n    if count != len(params):\n        raise UnsafeQuery('placeholder count mismatch')\n    parts = template.split('?')\n    rendered = parts[0]\n    for i, value in enumerate(params):\n        # WRONG: hand-rolled escaping \u2014 strips quotes, corrupting legit data\n        rendered += str(value).replace(\"'\", \"\") + parts[i + 1]\n    return rendered, 'parameterized'\n\n\ndef vulnerable_query(template, values):\n    '''The WRONG world: values are formatted straight into the SQL string.\n    Detects classic payloads and raises UnsafeQuery (i.e., flags that this\n    build path is unsafe for them).'''\n    rendered = template.format(*values)\n    lowered = rendered.lower()\n    if \"drop table\" in lowered or \"or 1=1\" in lowered or \";\" in lowered:\n        raise UnsafeQuery('injection detected in string-built query')\n    return rendered\n";
R["pa-sec-path-traversal"] = "from pathlib import PurePosixPath\n\n\ndef resolve_upload(base, name):\n    '''Return the resolved path inside `base` for a user-supplied file name,\n    or raise ValueError('traversal') if it escapes base. Absolute paths and\n    any '..' component are rejected; symlinks are not simulated.'''\n    if not name or name.startswith('/') or '\\x00' in name:\n        raise ValueError('traversal')\n    p = PurePosixPath(name)\n    if p.is_absolute() or '..' in p.parts:\n        raise ValueError('traversal')\n    resolved = PurePosixPath(base) / p\n    if not str(resolved).startswith(str(PurePosixPath(base)).rstrip('/') + '/'):\n        raise ValueError('traversal')\n    return str(resolved)\n";
