R["pa-sec-authz"] = "class Forbidden(Exception):\n    pass\n\n\nclass NotFound(Exception):\n    pass\n\n\nORDERS = {\n    'o1': {'owner': 'alice', 'total': 100},\n    'o2': {'owner': 'bob', 'total': 50},\n}\n\n\ndef get_order(session, order_id, admin=False):\n    '''Authorization done right: the check derives from the SESSION, never from\n    a client-supplied parameter. Admins may read anything; owners read their\n    own; strangers get NotFound (not Forbidden \u2014 don't confirm existence).'''\n    order = ORDERS.get(order_id)\n    if order is None:\n        raise NotFound('no such order')\n    if not admin and order['owner'] != session['user']:\n        raise NotFound('no such order')   # existence not confirmed\n    return dict(order)\n";
W["pa-sec-authz"] = "class Forbidden(Exception):\n    pass\n\n\nclass NotFound(Exception):\n    pass\n\n\nORDERS = {\n    'o1': {'owner': 'alice', 'total': 100},\n    'o2': {'owner': 'bob', 'total': 50},\n}\n\n\ndef get_order(session, order_id, admin=False):\n    order = ORDERS.get(order_id)\n    if order is None:\n        raise NotFound('no such order')\n    # WRONG: trusts the client's owner_id parameter instead of the session\n    if not admin and order['owner'] != session.get('as_user', session['user']):\n        raise Forbidden('not yours')\n    return dict(order)\n";
R["pa-sec-password-full"] = "BREACHED = {\"password123456\", \"correcthorsebattery\", \"letmein123456\"}\n\n\ndef check_password(pw):\n    if not isinstance(pw, str):\n        return False, ['must be a string']\n    problems = []\n    if len(pw) < 12:\n        problems.append('must be at least 12 characters')\n    if not any(c.isupper() for c in pw):\n        problems.append('must contain an uppercase letter')\n    if not any(c.islower() for c in pw):\n        problems.append('must contain a lowercase letter')\n    if not any(c.isdigit() for c in pw):\n        problems.append('must contain a digit')\n    if any(c.isspace() for c in pw):\n        problems.append('must not contain whitespace')\n    if pw.lower() in BREACHED:\n        problems.append('must not be a known breached password')\n    return (not problems), problems\n";
