R["pa-sec-gate"] = "def security_gate(handlers):\n    clean, vulnerable = [], []\n    for h in handlers:\n        checks = h['checks']\n        missing = []\n        entry = {'name': h['name']}\n        if h['public']:\n            suspicious = bool(checks & {'auth', 'owner'})\n            if suspicious:\n                entry['suspicious'] = True\n                entry['missing'] = ['unneeded-auth-checks']\n                vulnerable.append(entry)\n            else:\n                clean.append(h['name'])\n            continue\n        if 'auth' not in checks or 'owner' not in checks:\n            missing += [c for c in ('auth', 'owner') if c not in checks]\n            entry['critical'] = True\n        for c in ('params', 'encode'):\n            if c not in checks:\n                missing.append(c)\n        if missing:\n            entry['missing'] = sorted(missing)\n            vulnerable.append(entry)\n        else:\n            clean.append(h['name'])\n    vulnerable.sort(key=lambda e: (-len(e.get('missing', [])), e['name']))\n    return {'clean': clean, 'vulnerable': vulnerable}\n";
