R["pa-test-fake-clock"] = "class FakeClock:\n    '''Deterministic clock. starts at `start`; advance() moves it forward.'''\n\n    def __init__(self, start=0.0):\n        self.now_value = float(start)\n\n    def now(self):\n        return self.now_value\n\n    def advance(self, seconds):\n        assert seconds >= 0\n        self.now_value += seconds\n\n\nclass RateLimiter:\n    '''Allows `rate` events per window; driven by an injected clock.'''\n\n    def __init__(self, rate, window, clock):\n        self.rate = rate\n        self.window = window\n        self.clock = clock\n        self._events = []\n\n    def allow(self):\n        now = self.clock.now()\n        self._events = [t for t in self._events if now - t < self.window]\n        if len(self._events) < self.rate:\n            self._events.append(now)\n            return True\n        return False\n";
W["pa-test-fake-clock"] = "import time as _time\n\n\nclass FakeClock:\n    def __init__(self, start=0.0):\n        self.now_value = float(start)\n\n    def now(self):\n        return self.now_value\n\n    def advance(self, seconds):\n        assert seconds >= 0\n        self.now_value += seconds\n\n\nclass RateLimiter:\n    def __init__(self, rate, window, clock):\n        self.rate = rate\n        self.window = window\n        self.clock = clock\n        self._events = []\n\n    def allow(self):\n        # WRONG: reads the real clock \u2014 injected clock ignored, tests flaky\n        now = _time.time()\n        self._events = [t for t in self._events if now - t < self.window]\n        if len(self._events) < self.rate:\n            self._events.append(now)\n            return True\n        return False\n";
