R["pa-test-property-engine"] = "def check_roundtrip_codec(encode, decode, samples):\n    '''Mini property engine: for each sample, decode(encode(x)) must equal x.\n    Returns (passed, first_failure) where first_failure is the failing sample\n    (shrunk to its minimal core: for lists, the first bad element) or None.'''\n    for x in samples:\n        try:\n            if decode(encode(x)) != x:\n                return False, x\n        except Exception:\n            return False, x\n    return True, None\n\n\ndef shrink(samples, bad):\n    '''List shrinking: try removing elements while the property still fails;\n    return the minimal failing prefix-content list.'''\n    current = list(bad)\n    changed = True\n    while changed and len(current) > 1:\n        changed = False\n        for i in range(len(current)):\n            candidate = current[:i] + current[i + 1:]\n            ok, _ = check_roundtrip_codec(lambda v: v, lambda v: v, [candidate])\n            if ok is False:\n                current = candidate\n                changed = True\n                break\n    return current\n";
