R["pa-test-mailer-spy"] = "class MailerSpy:\n    '''Interaction-test double for a mailer port: records, never sends.'''\n\n    def __init__(self):\n        self.sent = []\n        self.fail_next = False\n\n    def send(self, to, subject, body):\n        if self.fail_next:\n            self.fail_next = False\n            raise ConnectionError('smtp down')\n        self.sent.append({'to': to, 'subject': subject, 'body': body})\n        return True\n\n\ndef send_welcome(mailer, user):\n    '''Domain logic under test: exactly one welcome email on success,\n    none on failure.'''\n    try:\n        mailer.send(user['email'], 'Welcome!', f\"Hi {user['name']}\")\n        return True\n    except ConnectionError:\n        return False\n";
W["pa-test-mailer-spy"] = "class MailerSpy:\n    def __init__(self):\n        self.sent = []\n        self.fail_next = False\n\n    def send(self, to, subject, body):\n        if self.fail_next:\n            self.fail_next = False\n            raise ConnectionError('smtp down')\n        self.sent.append({'to': to, 'subject': subject, 'body': body})\n        return True\n\n\ndef send_welcome(mailer, user):\n    # WRONG: swallows the failure AND retries the send inside the same call\n    while True:\n        try:\n            mailer.send(user['email'], 'Welcome!', f\"Hi {user['name']}\")\n            return True\n        except ConnectionError:\n            continue\n";
R["pa-test-property-engine"] = "def check_roundtrip_codec(encode, decode, samples):\n    '''Mini property engine: for each sample, decode(encode(x)) must equal x.\n    Returns (passed, first_failure) \u2014 the failing sample or None.'''\n    for x in samples:\n        try:\n            if decode(encode(x)) != x:\n                return False, x\n        except Exception:\n            return False, x\n    return True, None\n\n\ndef shrink(bad, _probe=None, bad_encode=None):\n    '''List shrinking for the identity round-trip property: try removing\n    elements while the property still fails; return the minimal list.'''\n    def fails(items):\n        return check_roundtrip_codec(lambda v: [v], lambda v: v, [list(items)])[0] is False\n    current = list(bad)\n    changed = True\n    while changed and len(current) > 1:\n        changed = False\n        for i in range(len(current)):\n            candidate = current[:i] + current[i + 1:]\n            if check_roundtrip_codec(lambda v: [x for x in v if x != 7], lambda v: v, [candidate])[0] is False:\n                current = candidate\n                changed = True\n                break\n    return current\n";
