R["pa-test-flaky-triage"] = "def diagnose_flaky(test_record):\n    '''test_record: {'name', 'uses_time': bool, 'uses_random_unseeded': bool,\n    'shared_state': bool, 'order_dependent': bool}\n    Returns (verdict, causes): verdict 'flaky' if any cause, else 'sound';\n    causes is a list of human-readable strings in fixed order:\n    time, randomness, shared state, order dependence.'''\n    causes = []\n    if test_record['uses_time']:\n        causes.append('reads the wall clock: inject a clock')\n    if test_record['uses_random_unseeded']:\n        causes.append('unseeded randomness: seed it')\n    if test_record['shared_state']:\n        causes.append('shared state: give each test its own world')\n    if test_record['order_dependent']:\n        causes.append('order-dependent: construct prerequisites in the test')\n    return ('flaky' if causes else 'sound', causes)\n";
W["pa-test-flaky-triage"] = "def diagnose_flaky(test_record):\n    # WRONG: order dependence ignored \u2014 the classic hidden flake\n    causes = []\n    if test_record['uses_time']:\n        causes.append('reads the wall clock: inject a clock')\n    if test_record['uses_random_unseeded']:\n        causes.append('unseeded randomness: seed it')\n    if test_record['shared_state']:\n        causes.append('shared state: give each test its own world')\n    return ('flaky' if causes else 'sound', causes)\n";
R["pa-test-runner"] = "def run_suite(tests, order=None):\n    '''tests: list of {'name', 'fn'}; fn() returns 'pass' or raises AssertionError.\n    order: optional explicit order of names to run (deterministic replay).\n    Returns {'passed': [names], 'failed': [names], 'errors': [names], 'skipped': [names]}\n    in execution order. AssertionError -> failed; anything else -> errors;\n    a name in `order` that doesn't exist is an error entry '<name>: no such test'.'''\n    by_name = {t['name']: t for t in tests}\n    if order is None:\n        sequence = list(tests)\n    else:\n        sequence = [by_name[n] for n in order if n in by_name]\n    result = {'passed': [], 'failed': [], 'errors': [], 'skipped': []}\n    if order is not None:\n        known = set(order)\n        for t in tests:\n            if t['name'] not in known:\n                result['skipped'].append(t['name'])\n        for n in order:\n            if n not in by_name:\n                result['errors'].append(f'{n}: no such test')\n    for t in sequence:\n        try:\n            outcome = t['fn']()\n            result['passed'].append(t['name'])\n        except AssertionError:\n            result['failed'].append(t['name'])\n        except Exception:\n            result['errors'].append(t['name'])\n    return result\n";
W["pa-test-runner"] = "def run_suite(tests, order=None):\n    by_name = {t['name']: t for t in tests}\n    if order is None:\n        sequence = list(tests)\n    else:\n        # WRONG: unknown names silently vanish \u2014 typos in the order list hide tests\n        sequence = [by_name[n] for n in order if n in by_name]\n    result = {'passed': [], 'failed': [], 'errors': [], 'skipped': []}\n    for t in sequence:\n        try:\n            t['fn']()\n            result['passed'].append(t['name'])\n        except Exception:\n            # WRONG: assertions and real errors conflated\n            result['failed'].append(t['name'])\n    return result\n";
R["pa-test-suite-audit"] = "def audit_suite(records):\n    sound, flaky = [], []\n    for r in records:\n        causes = any([r['uses_time'], r['uses_random_unseeded'], r['shared_state'], r['order_dependent']])\n        (flaky if causes else sound).append(r['name'])\n    return {'sound': sound, 'flaky': flaky}\n\n\ndef plan_fix(record):\n    plan = []\n    if record['uses_time']:\n        plan.append('reads the wall clock: inject a clock')\n    if record['uses_random_unseeded']:\n        plan.append('unseeded randomness: seed it')\n    if record['shared_state']:\n        plan.append('shared state: give each test its own world')\n    if record['order_dependent']:\n        plan.append('order-dependent: construct prerequisites in the test')\n    return plan\n";
