R["pa-pkg-semver"] = "import re as _re\n\n_SEMVER = _re.compile(r'^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$')\n\n\ndef parse_version(v):\n    m = _SEMVER.match(v)\n    if not m:\n        raise ValueError(f'invalid semver: {v}')\n    return tuple(int(p) for p in m.groups())\n\n\ndef bump(version, part):\n    major, minor, patch = parse_version(version)\n    if part == 'major':\n        return f'{major + 1}.0.0'\n    if part == 'minor':\n        return f'{major}.{minor + 1}.0'\n    if part == 'patch':\n        return f'{major}.{minor}.{patch + 1}'\n    raise ValueError(f'unknown part: {part}')\n\n\ndef compare(a, b):\n    A, B = parse_version(a), parse_version(b)\n    return (A > B) - (A < B)\n";
W["pa-pkg-semver"] = "import re as _re\n\n_SEMVER = _re.compile(r'^(\\d+)\\.(\\d+)\\.(\\d+)$')\n\n\ndef parse_version(v):\n    m = _SEMVER.match(v)\n    if not m:\n        raise ValueError(f'invalid semver: {v}')\n    return tuple(int(p) for p in m.groups())\n\n\ndef bump(version, part):\n    major, minor, patch = parse_version(version)\n    if part == 'major':\n        return f'{major + 1}.{minor}.{patch}'  # WRONG: keeps old minors\n    if part == 'minor':\n        return f'{major}.{minor + 1}.{patch}'  # WRONG: keeps old patch\n    if part == 'patch':\n        return f'{major}.{minor}.{patch + 1}'\n    raise ValueError(f'unknown part: {part}')\n\n\ndef compare(a, b):\n    A, B = parse_version(a), parse_version(b)\n    return (A > B) - (A < B)\n";
R["pa-pkg-plugin-registry"] = "def collect_plugins(registry, group):\n    '''registry: dict group -> list of (package, plugin_name, factory).\n    Returns {plugin_name: factory} for the group; a duplicate plugin name\n    raises ValueError('duplicate plugin: <name>'). Factories are not called.'''\n    plugins = {}\n    for package, name, factory in registry.get(group, []):\n        if name in plugins:\n            raise ValueError(f'duplicate plugin: {name}')\n        plugins[name] = factory\n    return plugins\n";
W["pa-pkg-plugin-registry"] = "def collect_plugins(registry, group):\n    plugins = {}\n    for package, name, factory in registry.get(group, []):\n        plugins[name] = factory  # WRONG: last-wins silently shadows plugins\n    return plugins\n";
R["pa-p14-atomic-write"] = "import os as _os\n\n\nclass AtomicStore:\n    '''File-backed store with atomic replace semantics (simulated in memory\n    but ordered exactly like the real pattern: write tmp -> flush -> replace).'''\n\n    def __init__(self):\n        self._files = {}\n        self._log = []\n\n    def write(self, path, data):\n        tmp = path + '.tmp'\n        self._log.append(('write', tmp))\n        self._log.append(('flush', tmp))\n        self._log.append(('replace', tmp, path))\n        self._files[path] = data\n        self._files.pop(tmp, None)\n\n    def read(self, path):\n        if path not in self._files:\n            raise FileNotFoundError(path)\n        return self._files[path]\n\n    @property\n    def log(self):\n        return list(self._log)\n\n\ndef graceful_shutdown(worker, sigterm=True, sigint=False):\n    '''Simulate signal handling. worker has: running (bool), in_flight (int),\n    drained (bool), requeued (list). SIGTERM/SIGINT -> stop accepting, finish\n    or requeue in-flight work, mark drained. Returns the worker.'''\n    if not (sigterm or sigint):\n        return worker  # SIGKILL: nothing graceful happens\n    worker.running = False          # stop accepting new work\n    if worker.in_flight:\n        worker.requeued.append(worker.in_flight)\n        worker.in_flight = 0\n    worker.drained = True\n    return worker\n";
W["pa-p14-atomic-write"] = "import os as _os\n\n\nclass AtomicStore:\n    def __init__(self):\n        self._files = {}\n        self._log = []\n\n    def write(self, path, data):\n        # WRONG: writes in place \u2014 a crash mid-write leaves a torn file\n        self._log.append(('write', path))\n        self._files[path] = data\n\n    def read(self, path):\n        if path not in self._files:\n            raise FileNotFoundError(path)\n        return self._files[path]\n\n    @property\n    def log(self):\n        return list(self._log)\n\n\ndef graceful_shutdown(worker, sigterm=True, sigint=False):\n    if not (sigterm or sigint):\n        return worker\n    worker.running = False\n    worker.in_flight = 0  # WRONG: work vanishes instead of being requeued\n    worker.drained = True\n    return worker\n";
R["pa-p14-structured-log"] = "import json as _json\n\n\nclass StructuredLogger:\n    '''Structured logger with redaction. Sensitive fields are replaced with\n    '[REDACTED]' at emit time; the event name and correlation id always ride\n    along.'''\n\n    SENSITIVE = {'password', 'token', 'secret', 'card_number'}\n\n    def __init__(self, correlation_id):\n        self.correlation_id = correlation_id\n        self.lines = []\n\n    def _redact(self, fields):\n        return {k: ('[REDACTED]' if k in self.SENSITIVE else v) for k, v in fields.items()}\n\n    def log(self, level, event, **fields):\n        line = {'level': level, 'event': event, 'correlation_id': self.correlation_id}\n        line.update(self._redact(fields))\n        self.lines.append(_json.dumps(line, sort_keys=True))\n\n    def info(self, event, **fields):\n        self.log('INFO', event, **fields)\n\n    def error(self, event, **fields):\n        self.log('ERROR', event, **fields)\n";
W["pa-p14-structured-log"] = "import json as _json\n\n\nclass StructuredLogger:\n    SENSITIVE = {'password', 'token', 'secret', 'card_number'}\n\n    def __init__(self, correlation_id):\n        self.correlation_id = correlation_id\n        self.lines = []\n\n    def log(self, level, event, **fields):\n        # WRONG: no redaction \u2014 secrets land in the log file\n        line = {'level': level, 'event': event, 'correlation_id': self.correlation_id}\n        line.update(fields)\n        self.lines.append(_json.dumps(line, sort_keys=True))\n\n    def info(self, event, **fields):\n        self.log('INFO', event, **fields)\n\n    def error(self, event, **fields):\n        self.log('ERROR', event, **fields)\n";
R["pa-p14-error-budget"] = "def error_budget(slo_success_rate, total, failures, window_days=30):\n    '''Return {'slo': rate, 'actual': rate, 'budget_remaining': fraction 0..1,\n    'status': 'healthy'|'burning'|'breached'}.\n    Budget: allowed failures = total * (1 - slo). remaining = 1 - failures/allowed\n    (0 when exhausted). status: healthy if remaining >= 0.5, burning if > 0,\n    breached otherwise (including when allowed is 0 and failures > 0).'''\n    allowed = total * (1 - slo_success_rate)\n    actual = (total - failures) / total if total else 1.0\n    if allowed <= 0:\n        remaining = 0.0 if failures > 0 else 1.0\n    else:\n        remaining = max(0.0, 1 - failures / allowed)\n    if remaining >= 0.5:\n        status = 'healthy'\n    elif remaining > 0:\n        status = 'burning'\n    else:\n        status = 'breached'\n    return {'slo': slo_success_rate, 'actual': actual,\n            'budget_remaining': remaining, 'status': status}\n";
W["pa-p14-error-budget"] = "def error_budget(slo_success_rate, total, failures, window_days=30):\n    allowed = total * (1 - slo_success_rate)\n    actual = (total - failures) / total if total else 1.0\n    # WRONG: budget never goes negative-aware \u2014 a breach still reads 'burning'\n    remaining = max(0.0, 1 - failures / allowed) if allowed else 1.0\n    if remaining >= 0.5:\n        status = 'healthy'\n    else:\n        status = 'burning'\n    return {'slo': slo_success_rate, 'actual': actual,\n            'budget_remaining': remaining, 'status': status}\n";
R["pa-p14-release-toolkit"] = "import json as _json\nimport re as _re\n\n_SEMVER = _re.compile(r'^(\\d+)\\.(\\d+)\\.(\\d+)$')\n\n\ndef next_release(version, changes):\n    m = _SEMVER.match(version)\n    if not m:\n        raise ValueError(f'invalid semver: {version}')\n    major, minor, patch = (int(p) for p in m.groups())\n    s = set(changes)\n    if 'breaking' in s:\n        return f'{major + 1}.0.0'\n    if 'feature' in s:\n        return f'{major}.{minor + 1}.0'\n    return f'{major}.{minor}.{patch + 1}'\n\n\ndef safe_registry(entries):\n    reg = {}\n    for group, name, factory in entries:\n        group_map = reg.setdefault(group, {})\n        if name in group_map:\n            raise ValueError(f'duplicate plugin: {name}')\n        group_map[name] = factory\n    return reg\n\n\n_SENSITIVE = {'password', 'token', 'secret', 'card_number'}\n\n\ndef incident_log(correlation_id, events):\n    lines = []\n    for level, event, fields in events:\n        line = {'level': level, 'event': event, 'correlation_id': correlation_id}\n        for k, v in fields.items():\n            line[k] = '[REDACTED]' if k in _SENSITIVE else v\n        lines.append(_json.dumps(line, sort_keys=True))\n    return lines\n";
W["pa-p14-release-toolkit"] = "import json as _json\nimport re as _re\n\n_SEMVER = _re.compile(r'^(\\d+)\\.(\\d+)\\.(\\d+)$')\n\n\ndef next_release(version, changes):\n    m = _SEMVER.match(version)\n    if not m:\n        raise ValueError(f'invalid semver: {version}')\n    major, minor, patch = (int(p) for p in m.groups())\n    # WRONG: ignores precedence \u2014 any change just bumps the patch\n    return f'{major}.{minor}.{patch + 1}'\n\n\ndef safe_registry(entries):\n    reg = {}\n    for group, name, factory in entries:\n        reg.setdefault(group, {})[name] = factory  # WRONG: silent shadowing\n    return reg\n\n\ndef incident_log(correlation_id, events):\n    lines = []\n    for level, event, fields in events:\n        line = {'level': level, 'event': event, 'correlation_id': correlation_id}\n        line.update(fields)  # WRONG: secrets land in the incident log\n        lines.append(_json.dumps(line, sort_keys=True))\n    return lines\n";
