R["pa-cap-core-loop"] = "class TaskFlowCore:\n    '''Milestones 1+2: the core loop with an idempotency gate, retry budget,\n    and a dead-letter tier with reasons.'''\n\n    def __init__(self):\n        self._pending = []        # [job_id, key, payload, attempts]\n        self._inflight = []\n        self._results = {}        # job_id -> result (idempotency store)\n        self._dead = {}           # job_id -> {'reason', 'attempts'}\n        self._metrics = {'submitted': 0, 'succeeded': 0, 'failed': 0, 'dead': 0}\n        self._keys_done = {}\n\n    def submit(self, key, payload):\n        '''Accept a job keyed by an idempotency key. Re-submits of a known key\n        replay the recorded outcome without re-executing. Returns the job id.'''\n        for job_id, k, payload0, attempts in self._pending + self._inflight:\n            if k == key:\n                return job_id   # already accepted; same job\n        if key in self._keys_done:\n            return self._keys_done[key]\n        self._metrics['submitted'] += 1\n        job_id = f'job-{self._metrics[\"submitted\"]}'\n        self._pending.append([job_id, key, payload, 0])\n        return job_id\n\n    def deliver(self):\n        batch = self._pending\n        self._pending = []\n        redeliver = self._inflight\n        self._inflight = [list(j) for j in batch]\n        self._inflight += [list(j) for j in redeliver]\n        return [list(j) for j in batch + redeliver]\n\n    def process(self, job_id, outcome):\n        '''Record a worker outcome for a delivered job. outcome=True -> success;\n        a string is a failure reason (consumes a retry attempt). Unknown jobs\n        are ignored (redelivery of a job already recorded).'''\n        for j in self._inflight:\n            if j[0] == job_id:\n                self._inflight.remove(j)\n                _, key, payload, attempts = j\n                if outcome is True:\n                    self._results[job_id] = {'status': 'succeeded', 'key': key, 'payload': payload}\n                    self._keys_done[key] = job_id\n                    self._metrics['succeeded'] += 1\n                else:\n                    attempts += 1\n                    self._metrics['failed'] += 1\n                    if attempts >= 3:\n                        self._dead[job_id] = {'status': 'dead', 'key': key, 'payload': payload,\n                                              'reason': outcome, 'attempts': attempts}\n                        self._keys_done[key] = job_id\n                        self._metrics['dead'] += 1\n                    else:\n                        self._pending.append([job_id, key, payload, attempts])\n                return\n\n    def status(self, job_id):\n        if job_id in self._results:\n            return dict(self._results[job_id])\n        if job_id in self._dead:\n            return dict(self._dead[job_id])\n        for j in self._inflight:\n            if j[0] == job_id:\n                return {'status': 'in_flight', 'key': j[1], 'payload': j[2]}\n        for j in self._pending:\n            if j[0] == job_id:\n                return {'status': 'pending', 'key': j[1], 'payload': j[2], 'attempts': j[3]}\n        return None\n\n    @property\n    def metrics(self):\n        return dict(self._metrics)\n";
W["pa-cap-core-loop"] = "class TaskFlowCore:\n    def __init__(self):\n        self._pending = []\n        self._inflight = []\n        self._results = {}\n        self._dead = {}\n        self._keys_done = {}\n        self._metrics = {'submitted': 0, 'succeeded': 0, 'failed': 0, 'dead': 0}\n\n    def submit(self, key, payload):\n        # WRONG: accepts duplicate keys as new jobs \u2014 exactly-once effects broken\n        self._metrics['submitted'] += 1\n        job_id = f'job-{self._metrics[\"submitted\"]}'\n        self._pending.append([job_id, key, payload, 0])\n        return job_id\n\n    def deliver(self):\n        batch = self._pending\n        self._pending = []\n        self._inflight = [list(j) for j in batch]\n        return [list(j) for j in batch]\n\n    def process(self, job_id, outcome):\n        for j in self._inflight:\n            if j[0] == job_id:\n                self._inflight.remove(j)\n                _, key, payload, attempts = j\n                if outcome is True:\n                    self._results[job_id] = {'status': 'succeeded', 'key': key, 'payload': payload}\n                    self._keys_done[key] = job_id\n                    self._metrics['succeeded'] += 1\n                else:\n                    attempts += 1\n                    self._metrics['failed'] += 1\n                    if attempts >= 3:\n                        self._dead[job_id] = {'status': 'dead', 'key': key, 'payload': payload,\n                                              'reason': outcome, 'attempts': attempts}\n                        self._keys_done[key] = job_id\n                        self._metrics['dead'] += 1\n                    else:\n                        self._pending.append([job_id, key, payload, attempts])\n                return\n\n    def status(self, job_id):\n        if job_id in self._results:\n            return dict(self._results[job_id])\n        if job_id in self._dead:\n            return dict(self._dead[job_id])\n        return None\n\n    @property\n    def metrics(self):\n        return dict(self._metrics)\n";
R["pa-cap-ops"] = "import json as _json\n\n\nclass TaskFlowOps:\n    '''Milestones 3+4: graceful shutdown/restart and operational surfaces.'''\n\n    SENSITIVE = {'password', 'token', 'secret', 'card_number'}\n\n    def __init__(self):\n        self.running = True\n        self.in_flight = 0\n        self.requeued = []\n        self.drained = False\n        self._lines = []\n        self._jobs = {}          # job_id -> principal\n        self._breaker_open = False\n\n    def shutdown(self):\n        self.running = False\n        if self.in_flight:\n            self.requeued.append(self.in_flight)\n            self.in_flight = 0\n        self.drained = True\n\n    def job(self, job_id, principal):\n        self._jobs[job_id] = principal\n\n    def status_for(self, job_id, principal):\n        '''Ownership from the principal, never a parameter; strangers get None.'''\n        owner = self._jobs.get(job_id)\n        if owner is None or owner != principal:\n            return None\n        return {'job_id': job_id}\n\n    def log(self, level, event, job_id=None, **fields):\n        line = {'level': level, 'event': event, 'correlation_id': job_id}\n        for k, v in fields.items():\n            line[k] = '[REDACTED]' if k in self.SENSITIVE else v\n        self._lines.append(_json.dumps(line, sort_keys=True))\n\n    @property\n    def lines(self):\n        return list(self._lines)\n\n    def trip_breaker(self):\n        self._breaker_open = True\n\n    def readiness(self):\n        '''Ready iff intake open and breaker closed; reports both probes.'''\n        return {'ready': self.running and not self._breaker_open,\n                'checks': {'intake': self.running, 'dependencies': not self._breaker_open}}\n";
W["pa-cap-ops"] = "import json as _json\n\n\nclass TaskFlowOps:\n    SENSITIVE = {'password', 'token', 'secret', 'card_number'}\n\n    def __init__(self):\n        self.running = True\n        self.in_flight = 0\n        self.requeued = []\n        self.drained = False\n        self._lines = []\n        self._jobs = {}\n        self._breaker_open = False\n\n    def shutdown(self):\n        self.running = False\n        self.in_flight = 0  # WRONG: in-flight work vanishes\n        self.drained = True\n\n    def job(self, job_id, principal):\n        self._jobs[job_id] = principal\n\n    def status_for(self, job_id, principal, as_user=None):\n        # WRONG: trusts the client-supplied as_user parameter\n        owner = self._jobs.get(job_id)\n        if owner is None or owner != (as_user or principal):\n            return None\n        return {'job_id': job_id}\n\n    def log(self, level, event, job_id=None, **fields):\n        line = {'level': level, 'event': event, 'correlation_id': job_id}\n        line.update(fields)  # WRONG: no redaction\n        self._lines.append(_json.dumps(line, sort_keys=True))\n\n    @property\n    def lines(self):\n        return list(self._lines)\n\n    def trip_breaker(self):\n        self._breaker_open = True\n\n    def readiness(self):\n        return {'ready': self.running}  # WRONG: ignores the breaker\n";
R["pa-cap-restart-safety"] = "class TaskFlowCore:\n    def __init__(self):\n        self._pending = []\n        self._inflight = []\n        self._results = {}\n        self._dead = {}\n        self._keys_done = {}\n        self._metrics = {'submitted': 0, 'succeeded': 0, 'failed': 0, 'dead': 0}\n        self.running = True\n\n    def submit(self, key, payload):\n        for job_id, k, payload0, attempts in self._pending + self._inflight:\n            if k == key:\n                return job_id\n        if key in self._keys_done:\n            return self._keys_done[key]\n        self._metrics['submitted'] += 1\n        job_id = f'job-{self._metrics[\"submitted\"]}'\n        self._pending.append([job_id, key, payload, 0])\n        return job_id\n\n    def deliver(self):\n        batch = self._pending\n        self._pending = []\n        redeliver = self._inflight\n        self._inflight = [list(j) for j in batch]\n        self._inflight += [list(j) for j in redeliver]\n        return [list(j) for j in batch + redeliver]\n\n    def process(self, job_id, outcome):\n        for j in self._inflight:\n            if j[0] == job_id:\n                self._inflight.remove(j)\n                _, key, payload, attempts = j\n                if outcome is True:\n                    self._results[job_id] = {'status': 'succeeded', 'key': key, 'payload': payload}\n                    self._keys_done[key] = job_id\n                    self._metrics['succeeded'] += 1\n                else:\n                    attempts += 1\n                    self._metrics['failed'] += 1\n                    if attempts >= 3:\n                        self._dead[job_id] = {'status': 'dead', 'key': key, 'payload': payload,\n                                              'reason': outcome, 'attempts': attempts}\n                        self._keys_done[key] = job_id\n                        self._metrics['dead'] += 1\n                    else:\n                        self._pending.append([job_id, key, payload, attempts])\n                return\n\n    def status(self, job_id):\n        if job_id in self._results:\n            return dict(self._results[job_id])\n        if job_id in self._dead:\n            return dict(self._dead[job_id])\n        for j in self._inflight:\n            if j[0] == job_id:\n                return {'status': 'in_flight', 'key': j[1], 'payload': j[2]}\n        for j in self._pending:\n            if j[0] == job_id:\n                return {'status': 'pending', 'key': j[1], 'payload': j[2], 'attempts': j[3]}\n        return None\n\n    def shutdown(self):\n        self.running = False\n        for j in self._inflight:\n            self._pending.append(j)\n        self._inflight = []\n\n    def restart(self):\n        self.running = True\n        self._metrics['restarted'] = True\n\n    @property\n    def metrics(self):\n        return dict(self._metrics)\n\n\ndef simulate_crash_restart(core):\n    a = core.submit('alpha', {'op': 1})\n    b = core.submit('beta', {'op': 2})\n    core.deliver()\n    core.shutdown()\n    core.restart()\n    batch = core.deliver()\n    for job_id, key, payload, attempts in batch:\n        core.process(job_id, True)\n    return {'a': core.status(a), 'b': core.status(b), 'metrics': core.metrics}\n";
